import json, os, time

# Check if any new worker results appeared recently
workers_dir = '/home/ubuntu/.agent-ml-research-idea_gen_0509_5/projects/contrastive_trace_safety/logs/workers'
now = time.time()
recent = []
for f in os.listdir(workers_dir):
    if f.endswith('_result.json'):
        mtime = os.path.getmtime(os.path.join(workers_dir, f))
        if now - mtime < 3600:  # last hour
            recent.append((f, mtime))
recent.sort(key=lambda x: x[1], reverse=True)
for f, mt in recent:
    age = int(now - mt)
    print(f'{age}s ago: {f}')

if not recent:
    print("No worker results in the last hour")

# Check active logs
active = []
for f in os.listdir(workers_dir):
    if f.endswith('.log') and not f.endswith('_result.json'):
        result_path = os.path.join(workers_dir, f.replace('.log', '_result.json'))
        if not os.path.exists(result_path):
            mtime = os.path.getmtime(os.path.join(workers_dir, f))
            if now - mtime < 3600:
                active.append((f, mtime))
active.sort(key=lambda x: x[1], reverse=True)
if active:
    print("\nActive workers (no result yet):")
    for f, mt in active:
        age = int(now - mt)
        print(f'  {age}s ago: {f}')
